    addEventListener('keydown', onKey); addEventListener('pointerdown', onFirst, true); addEventListener('keydown', onFirst, true);
    document.querySelectorAll('a[href^="#"]').forEach((a) => a.addEventListener('click', () => { if (!R.contains(a) || !a.matches('[data-tour-gate]')) { input.checked = false; D.on = false; } }));
    D.start = () => { D.active = true; D.last = null; R.classList.add('is-drifting'); };
    this.cleanup = () => { removeEventListener('wheel', onWheel); removeEventListener('touchmove', onWheel); removeEventListener('keydown', onKey); removeEventListener('pointerdown', onFirst, true); removeEventListener('keydown', onFirst, true); sw.remove(); };
    const pxps = () => this.stage.clientHeight * .3;
    const loop = (now) => {
      if (!this.alive) return;
      const dt = Math.min(.05, (now - D.lt) / 1000 || 0); D.lt = now;
      const endY = top() + span();
      if (D.active && D.on && !D.done && scrollY < endY - 1) {
        if (D.last !== null && Math.abs(scrollY - D.last) > 40) D.pos = scrollY;     // a scrollbar drag: carry on from there
        else if (D.last === null) D.pos = scrollY;
        D.pos = Math.min(endY, D.pos + pxps() * dt);
        scrollTo({ top: D.pos, behavior: 'instant' }); D.last = D.pos;
      }
      if (D.active && scrollY >= endY - 2) D.done = true;
      sw.classList.toggle('is-gone', !D.active || D.done);
      if (!this.frozen) this.render(tNow());
      requestAnimationFrame(loop);
    };
    requestAnimationFrame(loop);
  }

  /* swap in another script on the same window: the product goes back to how the page drew it, then the new
     script is compiled and measured. The playground uses it to turn a visitor's clicks into a live script. */
  load(script) {
    this.pause();
    for (const c of this.ch) { c.last = undefined; this.write(c, c.init); }
    this.S = script; this.compile();
    Object.assign(this.api, { duration: this.duration, chapters: this.chapters.map((c) => ({ t: c.start, n: c.n, title: c.title })), marks: this.marks });
    this.t = -1; this.layout(); this.grow(); this.probe();
    return this.api;
  }

  destroy() { this.alive = false; this.pause(); this.ro?.disconnect(); this.cleanup?.(); this.audio?.pause(); }
}

// demo/writer: a writer's and speaker's site.
//   the film      tour.js on the play driver, looping while it's on screen; the chapter titles become the words under
//                 it (click one to go there); ?record&ratio=16:9|1:1|9:16 films it once, ?t=12 freezes a moment
//   quoting       select any sentence in a [data-quotable] block (or click the marked line) and it becomes a card:
//                 a link straight to that line (#:~:text=, or #t= for a talk), an image to save, a post to share
//   the talk      a compact player: slides change at their data-at, the transcript follows and seeks when clicked;
//                 a <video> or <audio> inside .wr-pl-pip becomes its clock, otherwise it plays at data-demo-rate
//   the letter    the form posts to its action; with action="#" it just says thanks
import { Tour, include } from '../tour/tour.js';
import script from './script.js';

const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const mmss = (v) => `${Math.floor(v / 60)}:${String(Math.floor(v % 60)).padStart(2, '0')}`;

export default function init(root) {
  const off = []; let dead = false;
  start();
  return () => { dead = true; off.forEach((f) => f && f()); };

  async function start() {
    await include(root);                  // harvested fragments: <div data-tour-include="writer/fragments/…">
    if (dead) return;
    const film = root.querySelector('.wr-film');
    if (film) off.push(filmUp(film));
    root.querySelectorAll('[data-wr-player]').forEach((p) => off.push(player(p)));
    off.push(quotes(root), sweep(root));
    root.querySelectorAll('.wr-form').forEach((f) => off.push(letter(f)));
  }
}

/* the film, and its chapters as words with a progress line each */
function filmUp(film) {
  const tour = new Tour(film, script);
  film.tour = tour;                       // the instance, for the console
  const list = film.querySelector('.wr-steps'), ch = tour.chapters;
  list.innerHTML = ch.map((c, i) => `<li><button type="button" data-i="${i}"${tour.rec ? ' tabindex="-1"' : ''}><span>${c.title.replace(/<[^>]+>/g, '')}</span><i></i></button></li>`).join('');
  const items = [...list.children];
  const paint = (t) => items.forEach((li, i) => {
    const c = ch[i], p = Math.max(0, Math.min(1, (t - c.start) / (c.end - c.start)));
    li.style.setProperty('--p', p.toFixed(4)); li.classList.toggle('is-on', t >= c.start && t < c.end); li.classList.toggle('is-done', t >= c.end);
  });
  const prev = tour.onFrame; tour.onFrame = (t) => { prev?.(t); paint(t); };
  paint(Math.max(0, tour.t));
  const off = [() => tour.destroy()];
  if (tour.rec) return () => off.forEach((f) => f());

  let mine = false;                       // the visitor paused it themselves: don't autoplay over that
  const go = (e) => {
    const b = e.target.closest('button[data-i]'); if (!b) return;
    const c = ch[+b.dataset.i];
    if (tour.still) { tour.render((c.start + c.end) / 2, true); paint(tour.t); return; }
    if (!tour.begun) { tour.begun = true; film.classList.add('is-begun'); }
    tour.render(c.start + .01, true); tour.play(); mine = false;
  };
  list.addEventListener('click', go); off.push(() => list.removeEventListener('click', go));
  if (!tour.still) {
    const pp = (e) => { if (e.target.closest('.tour-pp')) mine = !tour.playing; };
    film.addEventListener('click', pp); off.push(() => film.removeEventListener('click', pp));
    const io = new IntersectionObserver(([e]) => {     // plays once a third of it is on screen; pauses once it's gone
      if (e.intersectionRatio >= .33 && !mine) { if (!tour.begun) tour.begin(); else if (!tour.playing) tour.play(); }
      if (!e.isIntersecting && tour.playing) tour.pause();
    }, { threshold: [0, .33] });
    io.observe(film); off.push(() => io.disconnect());
  }
  return () => off.forEach((f) => f());
}

/* the marked lines sweep in once, when they're read */
function sweep(root) {
  const marks = root.querySelectorAll('.wr-hl');
  if (reduce) { marks.forEach((m) => m.classList.add('is-in')); return null; }
  const io = new IntersectionObserver((es) => es.forEach((e) => { if (e.isIntersecting) { setTimeout(() => e.target.classList.add('is-in'), 250); io.unobserve(e.target); } }), { threshold: 1, rootMargin: '0px 0px -12% 0px' });
  marks.forEach((m) => io.observe(m));
  return () => io.disconnect();
}

/* select → Quote → a card with a link back to exactly that line */
function quotes(root) {
  const dlg = root.querySelector('.wr-qd'), pop = root.querySelector('.wr-qpop');
  if (!dlg || !pop) return null;
  const zones = [...root.querySelectorAll('[data-quotable]')];
  const q = dlg.querySelector('.wr-qc-q'), src = dlg.querySelector('.wr-qc-src'), code = dlg.querySelector('.wr-qd-url code');
  const btnCopy = dlg.querySelector('[data-act=copy]'), btnSave = dlg.querySelector('[data-act=save]'), aPost = dlg.querySelector('[data-act=post]');
  let pending = null, current = null, timer = 0;
  const off = [];
  const on = (el, ev, fn, o) => { el.addEventListener(ev, fn, o); off.push(() => el.removeEventListener(ev, fn, o)); };
  const clean = (s) => s.replace(/\s+/g, ' ').trim();
  const enc = (s) => encodeURIComponent(s).replace(/-/g, '%2D');
  // a text fragment: the whole line if it's short, else its first and last few words
  const fragment = (text) => {
    const w = text.split(' ');
    return ':~:text=' + (text.length <= 90 || w.length < 10 ? enc(text) : `${enc(w.slice(0, 5).join(' '))},${enc(w.slice(-5).join(' '))}`);
  };
  const linkFor = (zone, text, at) => {
    const u = new URL(zone.dataset.quoteHref && zone.dataset.quoteHref !== '#' ? zone.dataset.quoteHref : location.href, location.href);
    ['clean', 'thumb'].forEach((k) => u.searchParams.delete(k)); u.hash = at != null ? `t=${Math.floor(at)}` : fragment(text);
    return u.href.replace(/#%3A~%3A/, '#:~:');
  };
  const open = (text, zone, at) => {
    text = clean(text).replace(/^[“"']+|[”"']+$/g, '');
    if (!text) return;
    const href = linkFor(zone, text, at), title = zone.dataset.quoteTitle || document.title;
    current = { text, title, href, at };
    q.textContent = text; src.textContent = title + (at != null ? ` · at ${mmss(at)}` : '');
    code.textContent = href.replace(/^https?:\/\//, '');
    aPost.href = `https://x.com/intent/post?text=${encodeURIComponent(`“${text}”`)}&url=${encodeURIComponent(href)}`;
    btnCopy.textContent = 'Copy link';
    hidePop(); getSelection()?.removeAllRanges();
    dlg.showModal();
  };
  const hidePop = () => { pop.hidden = true; pending = null; };
  // a selection inside one paragraph grows to the whole sentences it touches, so half a word never ends up on a card
  const whole = (r, text) => {
    const blk = (n) => (n.nodeType === 1 ? n : n.parentElement)?.closest('p, li, blockquote');
    const b = blk(r.startContainer);
    if (!b || b !== blk(r.endContainer)) return text;
    const pre = document.createRange(); pre.selectNodeContents(b); pre.setEnd(r.startContainer, r.startOffset);
    const all = b.textContent, i = pre.toString().length, j = i + r.toString().length;
    let s0 = i; while (s0 > 0 && !/[.!?]\s/.test(all.slice(s0 - 2, s0))) s0--;
    let s1 = j; while (s1 < all.length && !/[.!?]/.test(all[s1 - 1] || '')) s1++;
    if (/^\d{1,2}:\d{2}/.test(all)) s0 = Math.max(s0, all.search(/\d[^\d:]/) + 1);     // a transcript line: leave its time out
    return clean(all.slice(s0, s1)) || text;
  };
  const check = () => {
    const s = getSelection();
    if (!s || s.isCollapsed || !s.rangeCount) return hidePop();
    const r = s.getRangeAt(0), zone = zones.find((z) => z.contains(r.commonAncestorContainer));
    const text = clean(s.toString());
    if (!zone || text.length < 4) return hidePop();
    const el = r.startContainer.nodeType === 1 ? r.startContainer : r.startContainer.parentElement;
    const at = el?.closest('[data-at]')?.dataset.at;
    pending = { text: whole(r, text), zone, at: at != null ? +at : null };
    const b = r.getBoundingClientRect(), x = Math.max(60, Math.min(innerWidth - 60, b.left + b.width / 2));
    pop.style.left = x + 'px'; pop.style.top = Math.max(52, b.top) + 'px'; pop.hidden = false;
  };
  on(document, 'selectionchange', () => { clearTimeout(timer); timer = setTimeout(check, 160); });
  on(window, 'scroll', () => { if (!pop.hidden) check(); }, { passive: true });
  on(pop, 'pointerdown', (e) => e.preventDefault());       // keep the selection while the button is pressed
  on(pop, 'click', () => pending && open(pending.text, pending.zone, pending.at));
  root.querySelectorAll('.wr-hl').forEach((m) => {
    const zone = m.closest('[data-quotable]'); if (!zone) return;
    on(m, 'click', () => { if (getSelection()?.isCollapsed !== false) open(m.textContent, zone); });
    on(m, 'keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); open(m.textContent, zone); } });
  });
  on(dlg, 'click', async (e) => {
    if (e.target === dlg) return dlg.close();               // a click on the paper around the card
    const act = e.target.closest('[data-act]')?.dataset.act;
    if (act === 'close') dlg.close();
    if (act === 'copy' && current) {
      try { await navigator.clipboard.writeText(current.href); btnCopy.textContent = 'Link copied'; }
      catch { getSelection()?.selectAllChildren(code); btnCopy.textContent = 'Press ⌘C to copy'; }
    }
    if (act === 'save' && current) cardImage(root, current);
  });
  return () => { clearTimeout(timer); off.forEach((f) => f()); };
}

/* the card as a 1600 × 900 image, drawn in the page's own type */
async function cardImage(root, { text, title, href, at }) {
  const css = getComputedStyle(root), v = (k, d) => css.getPropertyValue(k).trim() || d;
  const serif = 'Newsreader, Georgia, serif', sans = '"Inter Tight", system-ui, sans-serif';
  await Promise.all([document.fonts?.load(`italic 64px ${serif}`), document.fonts?.load(`500 26px ${sans}`)]).catch(() => {});
  const W = 1600, H = 900, c = document.createElement('canvas'); c.width = W; c.height = H;
  const g = c.getContext('2d');
  g.fillStyle = v('--page', '#f5f3ef'); g.fillRect(0, 0, W, H);
  g.save(); g.shadowColor = 'rgba(25,24,22,.16)'; g.shadowBlur = 70; g.shadowOffsetY = 30;
  g.fillStyle = v('--ph', '#fff'); g.fillRect(120, 96, W - 240, H - 192); g.restore();
  const x = 220, maxW = W - 440;
  g.fillStyle = v('--wr-mark-2', '#e4c96f'); g.font = `400 190px ${serif}`; g.fillText('“', x - 14, 300);
  let size = 66, lines = [];
  const wrap = () => {
    g.font = `italic 400 ${size}px ${serif}`; lines = []; let line = '';
    for (const w of text.split(' ')) { const t = line ? line + ' ' + w : w; if (g.measureText(t).width > maxW && line) { lines.push(line); line = w; } else line = t; }
    lines.push(line);
  };
  do { wrap(); size -= 4; } while (lines.length * size * 1.2 > 400 && size > 30);
  size += 4; g.fillStyle = v('--ink', '#191816');
  lines.forEach((l, i) => g.fillText(l, x, 340 + i * size * 1.18));
  g.fillStyle = v('--rule', '#d8d3c9'); g.fillRect(x, H - 230, maxW, 2);
  g.fillStyle = v('--ink', '#191816'); g.font = `600 26px ${sans}`;
  const name = root.querySelector('.wr-qc figcaption b')?.textContent || '';
  g.fillText(name, x, H - 180);
  g.fillStyle = v('--ink-2', '#5f5a53'); g.font = `400 26px ${sans}`; g.textAlign = 'right';
  g.fillText(title + (at != null ? ` · ${mmss(at)}` : ''), x + maxW, H - 180);
  g.textAlign = 'left'; g.fillStyle = v('--ink-3', '#9c968c'); g.font = `500 20px ui-monospace, Menlo, monospace`;
  g.fillText(new URL(href).host + new URL(href).pathname, x, H - 140);
  c.toBlob((b) => { if (!b) return; const a = document.createElement('a'); a.href = URL.createObjectURL(b); a.download = 'quote.png'; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 4000); });
}

/* the talk: slides and transcript lines carry data-at (seconds); one clock moves both */
function player(el) {
  const screen = el.querySelector('.wr-pl-screen'), slides = [...el.querySelectorAll('.wr-pl-slide')], lines = [...el.querySelectorAll('.wr-pl-script li')];
  const big = el.querySelector('.wr-pl-big'), pp = el.querySelector('.wr-pl-pp'), track = el.querySelector('.wr-pl-track');
  const range = track.querySelector('input'), time = el.querySelector('.wr-pl-time b'), pip = el.querySelector('.wr-pl-pip');
  const media = el.querySelector('video, audio');
  let dur = +el.dataset.dur || 600;
  const rate = media ? 1 : +el.dataset.demoRate || 1;
  let t = 0, playing = false, raf = 0, last = 0, iS = -1, iL = -1;
  const off = [];
  const on = (n, ev, fn) => { n?.addEventListener(ev, fn); off.push(() => n?.removeEventListener(ev, fn)); };
  const ticks = () => { track.querySelectorAll('i').forEach((i) => i.remove()); track.insertAdjacentHTML('beforeend', slides.slice(1).map((s) => `<i style="left:${(+s.dataset.at / dur) * 100}%"></i>`).join('')); range.max = dur; };
  const idx = (list) => { let i = 0; list.forEach((x, k) => { if (+x.dataset.at <= t + .01) i = k; }); return i; };
  const draw = () => {
    const s = idx(slides), l = idx(lines);
    if (s !== iS) { slides.forEach((x, k) => x.classList.toggle('is-on', k === s)); iS = s; }
    if (l !== iL) { lines.forEach((x, k) => { x.classList.toggle('is-on', k === l && (playing || t > 0)); x.classList.toggle('is-past', k < l); }); iL = l; }
    track.style.setProperty('--p', (t / dur).toFixed(4)); if (document.activeElement !== range) range.value = t;
    time.textContent = mmss(t);
  };
  const tick = (now) => {
    if (!playing) return;
    t = media ? media.currentTime : Math.min(dur, t + Math.min(.1, (now - last) / 1000) * rate); last = now;
    if (t >= dur) { t = dur; set(false); }
    draw(); raf = requestAnimationFrame(tick);
  };
  function set(p) {
    playing = p; pp.classList.toggle('is-playing', p); pp.setAttribute('aria-label', p ? 'Pause' : 'Play'); big.hidden = p || t > 0;
    if (media) p ? media.play().catch(() => {}) : media.pause();
    cancelAnimationFrame(raf); iL = -1;
    if (p) { if (t >= dur) t = 0; last = performance.now(); raf = requestAnimationFrame(tick); }
    draw();
  }
  const seek = (s) => { t = Math.max(0, Math.min(dur, s)); if (media) media.currentTime = t; iL = -1; big.hidden = true; draw(); };
  if (media) on(media, 'loadedmetadata', () => { dur = media.duration || dur; ticks(); draw(); });
  ticks();
  on(big, 'click', () => set(true));
  on(pp, 'click', () => set(!playing));
  on(range, 'input', () => seek(+range.value));
  on(pip, 'click', () => screen.classList.toggle('is-swapped'));
  lines.forEach((li) => on(li, 'click', () => { if (getSelection()?.isCollapsed === false) return; seek(+li.dataset.at); if (!playing) set(true); }));
  // pause when it scrolls away
  const io = new IntersectionObserver(([e]) => { if (!e.isIntersecting && playing) set(false); }, { threshold: .15 });
  io.observe(el); off.push(() => io.disconnect());
  draw();
  return () => { cancelAnimationFrame(raf); off.forEach((f) => f()); };
}

/* the letter: posts to the newsletter service; with action="#" it only says thanks */
function letter(form) {
  const done = form.parentElement.querySelector('.wr-form-done');
  const submit = (e) => {
    if ((form.getAttribute('action') || '#') !== '#') return;
    e.preventDefault(); form.hidden = true; if (done) { done.hidden = false; done.tabIndex = -1; done.focus(); }
  };
  form.addEventListener('submit', submit);
  return () => form.removeEventListener('submit', submit);
}

/* StyleFeatures scaffolds: the shared placeholder kit.
   Every scaffold section links this first. Tokens can be overridden per site in site.json "theme". */
:root{
  --page:#f5f3ef;--page-2:#ece9e3;--ph:#ffffff;--ph-line:#e3dfd7;--ph-mark:#d9d4ca;
  --ink:#191816;--ink-2:#5f5a53;--ink-3:#9c968c;--rule:#d8d3c9;
  --note:#c2643f;--note-bg:#fbf1ea;
  --serif:'Newsreader',Georgia,serif;--sans:'Inter Tight',system-ui,-apple-system,sans-serif;--mono:ui-monospace,'SF Mono',Menlo,monospace;
  --gutter:clamp(16px,3.4vw,48px);--max:1280px;--radius:2px;
  --ease:cubic-bezier(.2,.7,.2,1);
}
*{box-sizing:border-box}
html{background:var(--page);-webkit-text-size-adjust:100%}
body{margin:0;background:var(--page);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased;overflow-x:hidden}
a{color:inherit}
img{display:block;max-width:100%}
.sf-wrap{max-width:var(--max);margin:0 auto;padding-inline:var(--gutter)}
.sf-sec{padding-block:clamp(72px,12vh,140px)}

/* ── type ───────────────────────────────────────────── */
.sf-eyebrow{margin:0 0 18px;font:500 12px/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}
.sf-h1{margin:0;font:400 clamp(44px,6.4vw,96px)/.98 var(--serif);letter-spacing:-.025em}
.sf-h2{margin:0;font:400 clamp(32px,4vw,58px)/1.02 var(--serif);letter-spacing:-.02em}
.sf-h3{margin:0;font:500 clamp(19px,1.6vw,23px)/1.2 var(--sans);letter-spacing:-.01em}
.sf-lede{margin:0;max-width:34em;font:400 clamp(17px,1.4vw,20px)/1.5 var(--sans);color:var(--ink-2)}
.sf-small{font:400 13px/1.45 var(--sans);color:var(--ink-3)}

/* ── placeholder image: <figure class="ph" style="--r:4/5" data-ph="Image · 4:5" data-hint="What goes here"></figure> */
.ph{position:relative;margin:0;aspect-ratio:var(--r,4/3);background:var(--ph);border-radius:var(--radius);overflow:hidden;
  box-shadow:inset 0 0 0 1px var(--ph-line);min-width:0}
.ph::before{content:"";position:absolute;inset:0;pointer-events:none;
  background:
    linear-gradient(to top right,transparent calc(50% - .5px),var(--ph-mark) calc(50% - .5px),var(--ph-mark) calc(50% + .5px),transparent calc(50% + .5px)),
    linear-gradient(to bottom right,transparent calc(50% - .5px),var(--ph-mark) calc(50% - .5px),var(--ph-mark) calc(50% + .5px),transparent calc(50% + .5px));
  opacity:.55}
.ph::after{content:attr(data-ph) "\A" attr(data-hint);white-space:pre-line;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  width:max-content;max-width:min(80%,24em);padding:9px 13px;background:var(--ph);text-align:center;
  font:500 11px/1.45 var(--sans);letter-spacing:.06em;text-transform:uppercase;color:var(--ink-3);border-radius:var(--radius)}
.ph[data-hint]::after{font-size:11px}
.ph.is-bare::after{content:none}
.ph.is-round{border-radius:50%}
.ph.is-tone{--ph:var(--page-2)}              /* a placeholder on a white card */
.ph > *{position:relative;z-index:1}

/* video placeholder: add .ph-video; scaffold.js adds the transport */
.ph-video{--ph:#f7f6f3}
.ph-video::before{opacity:.35}
.ph-video::after{top:auto;bottom:44px;transform:translateX(-50%);max-width:min(86%,26em)}   /* label sits low, clear of the play button */
.ph-play{position:absolute;z-index:2;left:50%;top:50%;width:56px;height:56px;margin:-28px 0 0 -28px;border:0;border-radius:50%;
  background:var(--ink);color:var(--page);cursor:pointer;display:grid;place-items:center;transition:transform .4s var(--ease)}
.ph-play:hover{transform:scale(1.06)}
.ph-play[hidden],.ph-bar[hidden]{display:none}
.ph-play svg{width:20px;height:20px}
.ph-play:focus-visible{outline:2px solid var(--note);outline-offset:4px}
.ph-bar{position:absolute;z-index:2;left:16px;right:16px;bottom:14px;display:flex;align-items:center;gap:12px;font:500 11px/1 var(--mono);color:var(--ink-3)}
.ph-track{flex:1;height:2px;background:var(--ph-line);position:relative;overflow:hidden}
.ph-track i{position:absolute;inset:0;background:var(--ink);transform-origin:left;transform:scaleX(var(--p,0))}
.ph-video.is-playing::before{animation:ph-breathe 3.2s ease-in-out infinite}
@keyframes ph-breathe{50%{opacity:.12}}

/* placeholder copy: <p class="ph-text" style="--n:3"></p>  (n lines, last one short) */
.ph-text{--lh:1.6em;display:block;margin:0;height:calc(var(--n,3) * var(--lh));max-width:32em;
  background:repeating-linear-gradient(to bottom,var(--ph-line) 0 .55em,transparent .55em var(--lh));
  -webkit-mask:linear-gradient(#000,#000) top/100% calc(100% - var(--lh)) no-repeat,linear-gradient(90deg,#000 var(--last,58%),transparent 0) bottom/100% var(--lh) no-repeat;
          mask:linear-gradient(#000,#000) top/100% calc(100% - var(--lh)) no-repeat,linear-gradient(90deg,#000 var(--last,58%),transparent 0) bottom/100% var(--lh) no-repeat}
.ph-logo{display:inline-flex;align-items:center;justify-content:center;height:34px;min-width:110px;padding:0 14px;border-radius:var(--radius);
  box-shadow:inset 0 0 0 1px var(--ph-line);background:var(--ph);font:600 11px/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}

/* ── controls ───────────────────────────────────────── */
.sf-btn{display:inline-flex;align-items:center;gap:10px;padding:14px 22px;border:0;border-radius:var(--radius);background:var(--ink);color:var(--page);
  font:500 14px/1 var(--sans);text-decoration:none;cursor:pointer;transition:background-color .3s ease,color .3s ease,box-shadow .3s ease}
.sf-btn:hover{background:#000}
.sf-btn--ghost{background:transparent;color:var(--ink);box-shadow:inset 0 0 0 1px var(--ink)}
.sf-btn--ghost:hover{background:var(--ink);color:var(--page)}
.sf-btn--text{padding:6px 0;background:none;color:var(--ink);box-shadow:inset 0 -1px 0 currentColor}
.sf-btn--text:hover{background:none;color:var(--ink-2)}
.sf-btn:focus-visible,.sf-field:focus-visible{outline:2px solid var(--note);outline-offset:3px}
.sf-field{width:100%;padding:14px 0;border:0;border-bottom:1px solid var(--rule);background:transparent;font:400 16px/1.2 var(--sans);color:var(--ink);border-radius:0}
.sf-field::placeholder{color:var(--ink-3)}
.sf-rule{height:0;border:0;border-top:1px solid var(--rule);margin:0}

/* ── notes: what goes here / who it suits. <span class="sf-note">Swap for your logo</span>; html.sf-clean hides them */
.sf-note{display:inline-flex;align-items:center;gap:7px;padding:5px 9px 5px 7px;border-radius:var(--radius);background:var(--note-bg);color:var(--note);
  font:500 11px/1.25 var(--sans);letter-spacing:.01em;vertical-align:middle;white-space:normal;max-width:30em}
.sf-note::before{content:"";flex:none;width:6px;height:6px;border-radius:50%;background:currentColor}
.sf-note.is-pin{position:absolute;z-index:5}
html.sf-clean .sf-note{display:none!important}

/* ── reveal ─────────────────────────────────────────── */
[data-reveal]{opacity:0;transform:translateY(14px);transition:opacity 1s var(--ease),transform 1.2s var(--ease);transition-delay:calc(var(--i,0) * 80ms)}
[data-reveal].is-in{opacity:1;transform:none}
.no-js [data-reveal]{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){[data-reveal]{opacity:1;transform:none;transition:none}}

/* ── preview spec card (only on preview pages) ───────── */
.sf-spec{position:fixed;z-index:9999;left:14px;bottom:14px;max-width:min(360px,calc(100vw - 28px));padding:14px 16px;border-radius:4px;
  background:rgba(255,255,255,.94);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);box-shadow:0 0 0 1px var(--ph-line),0 10px 30px -14px rgba(0,0,0,.3);
  font:400 12px/1.45 var(--sans);color:var(--ink-2)}
.sf-spec b{display:block;font:500 14px/1.25 var(--sans);color:var(--ink);margin:6px 0 3px}
.sf-spec .sf-kind{margin-right:6px}
.sf-spec ul{list-style:none;margin:8px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:5px}
.sf-spec li{padding:3px 7px;border-radius:2px;background:var(--page);color:var(--ink-2);font-size:11px}
.sf-spec button{margin-top:10px;padding:0;border:0;background:none;font:500 11px/1 var(--sans);color:var(--ink-3);text-decoration:underline;cursor:pointer}
.sf-spec.is-min p,.sf-spec.is-min ul{display:none}
.sf-thumb .sf-spec{display:none}
@media (max-width:700px){.sf-spec{left:8px;bottom:8px;padding:10px 12px}}
.sf-kind{display:inline-flex;align-items:center;gap:6px;padding:4px 8px 4px 7px;border-radius:2px;font:600 10px/1 var(--sans);letter-spacing:.12em;text-transform:uppercase}
.sf-kind::before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor}
.sf-kind--static{background:#eceae5;color:#6f6a62}
.sf-kind--interactive{background:#fbeee6;color:#b65a35}
.sf-kind--video{background:#1d1c1a;color:#f2efe9}

/* tour.css: the engine's own look. Window chromes, the cursor, ripples, chapter card, caption, key caps,
   the play controls, the auto-play switch and the ?record stage. Shared by every demo film; a template
   restyles it through these tokens rather than editing it:
     --tour-stage  backdrop behind the window        --tour-win-radius  window corners (design px)
     --tour-ring   click ripple colour               --tour-cap-bg / --tour-cap-ink  caption pill
   Sizes on the stage scale with --su (a hundredth of the stage's short side, set by tour.js). */

[data-tour-root]{position:relative;--tour-stage:var(--page-2,#ece9e3);--tour-ring:rgba(25,24,22,.42);--tour-cap-bg:var(--ink,#191816);--tour-cap-ink:var(--page,#f5f3ef);--tour-win-radius:12px}
[data-tour-stage]{position:sticky;top:0;height:100svh;overflow:hidden;background:var(--tour-stage);isolation:isolate;--su:9px}
[data-tour-root].is-play [data-tour-stage],[data-tour-root].is-still [data-tour-stage]{position:relative}
.tour-rig{position:absolute;inset:0}

/* the window: design pixels, scaled by the camera */
[data-tour-window]{position:absolute;left:0;top:0;transform-origin:0 0;display:flex;flex-direction:column;overflow:hidden;
  border-radius:var(--tour-win-radius);background:var(--ph,#fff);
  box-shadow:0 0 0 1px rgba(25,24,22,.12),0 40px 90px -40px rgba(25,24,22,.5),0 12px 28px -16px rgba(25,24,22,.28)}
[data-tour-window] > :not(.tour-chrome){flex:1;min-height:0}
.tour-chrome{flex:none;height:40px;display:flex;align-items:center;gap:14px;padding:0 14px;background:var(--page,#f5f3ef);border-bottom:1px solid var(--ph-line,#e3dfd7);font:500 12.5px/1 var(--sans,system-ui);color:var(--ink-2,#5f5a53)}
.tour-lights{display:flex;gap:8px}
.tour-lights i{width:12px;height:12px;border-radius:50%;background:#ec6a5e;box-shadow:inset 0 0 0 .5px rgba(0,0,0,.12)}
.tour-lights i+i{background:#f4bf4f}.tour-lights i+i+i{background:#61c554}
.tour-navs{display:flex;gap:10px}.tour-navs.is-end{margin-left:auto}
.tour-chrome svg{width:15px;height:15px;fill:none;stroke:var(--ink-3,#9c968c);stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.tour-url{flex:0 1 420px;margin-left:auto;display:flex;align-items:center;justify-content:center;gap:7px;height:26px;padding:0 14px;border-radius:7px;background:var(--ph,#fff);box-shadow:inset 0 0 0 1px var(--ph-line,#e3dfd7);font-weight:400;color:var(--ink-2,#5f5a53);white-space:nowrap;overflow:hidden}
.tour-url svg{width:12px;height:12px}
.tour-chrome[data-kind=app]{height:38px;justify-content:center;position:relative}
.tour-chrome[data-kind=app] .tour-lights{position:absolute;left:14px;top:13px}
.tour-chrome[data-kind=phone]{height:46px;justify-content:space-between;padding:0 26px;background:transparent;border:0;font:600 15px/1 var(--sans,system-ui);color:var(--ink,#191816)}
.tour-notch{width:120px;height:32px;border-radius:20px;background:#111}
.tour-status{display:flex;gap:4px}.tour-status i{width:16px;height:10px;border-radius:2px;background:var(--ink,#191816)}
[data-chrome=phone]{--tour-win-radius:54px;box-shadow:0 0 0 10px #111,0 0 0 11px #333,0 40px 90px -30px rgba(25,24,22,.55)}
[data-chrome=none]{--tour-win-radius:8px}
/* terminal: a warm charcoal window (tokens --tour-term-bg, --tour-term-bar, --tour-term-ink, --tour-term-dim) */
[data-chrome=terminal]{background:var(--tour-term-bg,#1d1b18);color:var(--tour-term-ink,#ebe5d9)}
.tour-chrome[data-kind=terminal]{height:38px;justify-content:center;position:relative;background:var(--tour-term-bar,#272420);border-bottom:1px solid rgba(255,255,255,.07);color:var(--tour-term-dim,#a39b8e);font-weight:500}
.tour-chrome[data-kind=terminal] .tour-lights{position:absolute;left:14px;top:13px}
.tour-chrome[data-kind=terminal] .tour-lights i{box-shadow:inset 0 0 0 .5px rgba(0,0,0,.3)}
/* windows inside the window: any [data-chrome] element in the product gets its own chrome and frame */
[data-tour-window] [data-chrome]{display:flex;flex-direction:column;overflow:hidden;border-radius:var(--tour-win-radius)}
[data-tour-window] [data-chrome] > :not(.tour-chrome){flex:1;min-height:0}

/* cursor and ripples (stage coordinates) */
.tour-cur{position:absolute;left:0;top:0;z-index:8;width:0;height:0;pointer-events:none;opacity:0;transform-origin:0 0}
.tour-cur svg{position:absolute;left:-1px;top:-1px;overflow:visible;filter:drop-shadow(0 1px 1.5px rgba(0,0,0,.35)) drop-shadow(0 3px 6px rgba(0,0,0,.12))}
.tour-cur .tour-arrow path{fill:#141312;stroke:#fff;stroke-width:1.3}
.tour-cur .tour-hand{left:-8px;top:-2px}
.tour-cur .tour-hand path{fill:#fff;stroke:#141312;stroke-width:1.1}
.tour-cur .tour-beam{left:-5px;top:-12px}
.tour-cur .tour-beam path{stroke:#141312;stroke-width:1.6;paint-order:stroke}
.tour-cur[data-look=light] .tour-arrow path{fill:#fff;stroke:#141312;stroke-width:1.1}
.tour-ring{position:absolute;left:0;top:0;z-index:7;width:46px;height:46px;margin:-23px 0 0 -23px;border-radius:50%;border:2.5px solid var(--tour-ring);background:color-mix(in srgb,var(--tour-ring) 18%,transparent);pointer-events:none;opacity:0}
/* pointer:'touch': a fingertip (44 window px, it zooms with the screen) instead of the arrow; tour.js sets its opacity and size */
.tour-touch{display:none;position:absolute;left:-22px;top:-22px;width:44px;height:44px;border-radius:50%;background:var(--tour-touch,rgba(112,112,120,.36));
  box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.62),0 0 0 1px rgba(20,19,18,.1),0 3px 12px -3px rgba(20,19,18,.32)}
.tour-cur.is-down .tour-touch{background:var(--tour-touch-down,rgba(92,92,100,.48));box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.7),0 0 0 1px rgba(20,19,18,.12),0 1px 5px -1px rgba(20,19,18,.3)}
.is-touch .tour-touch{display:block}
.is-touch .tour-cur svg{display:none!important}
.is-touch .tour-ring{width:44px;height:44px;margin:-22px 0 0 -22px;border:1.5px solid rgba(112,112,120,.55);background:none}
/* more than one pointer (steps with { by: 'agent' }): its own colour (--tour-agent) and a label tag; the person's
   cursor gets a tag too when pointers.main.label is set */
.tour-cur[data-look=agent] .tour-arrow path{fill:var(--tour-agent,#3b4bc8);stroke:#fff;stroke-width:1.4}
.tour-cur[data-look=agent] svg{filter:drop-shadow(0 1px 1.5px rgba(0,0,0,.25)) drop-shadow(0 0 7px color-mix(in srgb,var(--tour-agent,#3b4bc8) 45%,transparent))}
.tour-tag{position:absolute;left:13px;top:21px;display:flex;align-items:center;gap:6px;height:22px;padding:0 8px;border-radius:6px;background:var(--ink,#191816);color:#fff;
  font:600 11.5px/1 var(--sans,system-ui);letter-spacing:.01em;white-space:nowrap;box-shadow:0 4px 12px -4px rgba(0,0,0,.35)}
.tour-tag span{font:500 11px/1 var(--mono,ui-monospace,monospace);opacity:.82}
.tour-tag span[hidden]{display:none}
.tour-cur[data-look=agent] .tour-tag{background:var(--tour-agent,#3b4bc8)}
.tour-ring[data-who]:not([data-who=main]){--tour-ring:var(--tour-agent,#3b4bc8)}

/* chapter card: "02 / 05", a title with one italic word, one line */
.tour-card{position:absolute;z-index:6;left:var(--gutter,32px);bottom:var(--gutter,32px);width:min(calc(var(--su)*44),calc(100% - 2 * var(--gutter,32px)));
  padding:calc(var(--su)*1.8) calc(var(--su)*2.1) calc(var(--su)*2);background:var(--ph,#fff);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 20px 44px -24px rgba(25,24,22,.45);
  opacity:0;transform:translateY(calc((1 - var(--o,0)) * 10px));pointer-events:none}
.tour-card-n{font:500 max(10.5px,calc(var(--su)*1.15))/1 var(--sans,system-ui);letter-spacing:.14em;color:var(--ink-3,#9c968c)}
.tour-card h3{margin:calc(var(--su)*1) 0 calc(var(--su)*.75);font:400 max(25px,calc(var(--su)*3.7))/1 var(--serif,Georgia,serif);letter-spacing:-.018em;color:var(--ink,#191816)}
.tour-card h3 em{font-style:italic}
.tour-card p{margin:0;font:400 max(13.5px,calc(var(--su)*1.7))/1.45 var(--sans,system-ui);color:var(--ink-2,#5f5a53)}
.tour-card,.tour-cap{transition:translate .55s cubic-bezier(.2,.7,.2,1)}
.tour-card[data-dodge=hide]{opacity:0!important}
.tour-card[data-dodge=off]{display:none}
.tour-card-x{position:absolute;top:calc(var(--su)*.9);right:calc(var(--su)*.9);width:max(26px,calc(var(--su)*2.8));height:max(26px,calc(var(--su)*2.8));display:grid;place-items:center;
  padding:0;border:0;border-radius:50%;background:transparent;color:var(--ink-3,#9c968c);font:400 max(16px,calc(var(--su)*1.9))/1 var(--sans,system-ui);cursor:pointer;pointer-events:auto;opacity:.7}
.tour-card-x:hover{opacity:1;background:var(--ph-line,#e3dfd7);color:var(--ink,#191816)}
.tour-card-x:focus-visible{outline:2px solid var(--tour-ring,#c2643f);outline-offset:2px;opacity:1}
.is-stack .tour-card{left:4%;right:4%;width:auto;bottom:auto;top:var(--card-top);padding:calc(var(--su)*2) calc(var(--su)*2.4)}
[data-tour-root].is-play:not(.is-stack) .tour-card{bottom:calc(var(--gutter,32px) + 46px)}

/* caption line: burned into recordings, because X autoplays muted */
.tour-cap{position:absolute;z-index:7;left:50%;bottom:calc(var(--su)*4);margin:0;max-width:min(calc(var(--su)*72),calc(100% - 2 * var(--gutter,32px)));width:max-content;
  padding:calc(var(--su)*1.05) calc(var(--su)*1.9);border-radius:calc(var(--su)*.6);background:var(--tour-cap-bg);color:var(--tour-cap-ink);
  font:500 max(14px,calc(var(--su)*2.35))/1.3 var(--sans,system-ui);letter-spacing:-.005em;text-align:center;opacity:0;transform:translate(-50%,calc((1 - var(--o,0)) * 8px));pointer-events:none;text-wrap:balance}
.is-stack .tour-cap{bottom:calc(var(--su)*5)}
.is-stack.is-tall .tour-cap{bottom:auto;top:var(--cap-top)}
[data-tour-root].is-play .tour-cap{bottom:calc(var(--su)*4 + 46px)}

/* key caps */
.tour-keys{position:absolute;z-index:7;display:flex;gap:calc(var(--su)*.6);transform:translate(-50%,calc((1 - var(--o,0)) * 8px));opacity:0;pointer-events:none}
.tour-keys kbd{min-width:calc(var(--su)*5.4);height:calc(var(--su)*5.4);padding:0 calc(var(--su)*1.2);display:grid;place-items:center;border-radius:calc(var(--su)*.9);
  background:var(--ph,#fff);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 calc(var(--su)*.35) 0 var(--ph-line,#e3dfd7),0 14px 30px -16px rgba(25,24,22,.5);
  font:500 calc(var(--su)*2.4)/1 var(--sans,system-ui);color:var(--ink,#191816)}

/* play driver: one quiet bar */
.tour-ctl{position:absolute;z-index:9;left:50%;bottom:14px;transform:translateX(-50%);display:flex;align-items:center;gap:12px;width:min(620px,calc(100% - 28px));
  padding:7px 14px 7px 7px;border-radius:999px;background:color-mix(in srgb,var(--ph,#fff) 92%,transparent);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 12px 30px -18px rgba(25,24,22,.5);
  font:500 11.5px/1 var(--mono,ui-monospace,monospace);color:var(--ink-2,#5f5a53)}
.tour-pp{flex:none;width:32px;height:32px;border:0;border-radius:50%;display:grid;place-items:center;background:var(--ink,#191816);color:var(--page,#f5f3ef);cursor:pointer}
.tour-pp svg{width:13px;height:13px;fill:currentColor}
.tour-pp:focus-visible,.tour-scrub input:focus-visible{outline:2px solid var(--note,#c2643f);outline-offset:3px}
.tour-scrub{position:relative;flex:1;height:20px;display:flex;align-items:center}
.tour-scrub::before{content:"";position:absolute;left:0;right:0;height:2px;background:var(--ph-line,#e3dfd7)}
.tour-scrub::after{content:"";position:absolute;left:0;height:2px;width:calc(var(--v,0) * 100%);background:var(--ink,#191816)}
.tour-scrub i{position:absolute;top:5px;width:1px;height:10px;background:var(--ink-3,#9c968c)}
.tour-scrub input{position:relative;z-index:1;width:100%;margin:0;background:none;-webkit-appearance:none;appearance:none;cursor:pointer;height:20px}
.tour-scrub input::-webkit-slider-thumb{-webkit-appearance:none;width:12px;height:12px;border-radius:50%;background:var(--ink,#191816)}
.tour-scrub input::-moz-range-thumb{width:12px;height:12px;border:0;border-radius:50%;background:var(--ink,#191816)}
.tour-time{flex:none;min-width:84px;text-align:right}
[data-tour-root]:not(.is-begun) .tour-ctl{opacity:0;pointer-events:none}
.tour-ctl{transition:opacity .4s ease}
.is-stack .tour-time{display:none}

/* scroll driver: the auto-play switch, the only way to take over while it plays itself */
.tour-drift{position:absolute;z-index:9;right:var(--gutter,16px);bottom:16px;display:flex;align-items:center;gap:10px;padding:7px 8px 7px 14px;border-radius:999px;
  background:color-mix(in srgb,var(--ph,#fff) 88%,transparent);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 10px 26px -14px rgba(25,24,22,.45);
  font:500 12px/1 var(--sans,system-ui);color:var(--ink,#191816);cursor:pointer;user-select:none;transition:opacity .5s ease,transform .5s cubic-bezier(.2,.7,.2,1)}
.tour-drift input{position:absolute;opacity:0;pointer-events:none}
.tour-drift > i{position:relative;width:34px;height:20px;border-radius:999px;background:var(--ink,#191816);transition:background-color .25s}
.tour-drift > i::after{content:"";position:absolute;top:3px;left:17px;width:14px;height:14px;border-radius:50%;background:var(--page,#f5f3ef);transition:left .3s cubic-bezier(.2,.7,.2,1)}
.tour-drift:has(input:not(:checked)) > i{background:var(--rule,#d8d3c9)}
.tour-drift:has(input:not(:checked)) > i::after{left:3px}
.tour-drift:has(input:focus-visible){outline:2px solid var(--note,#c2643f);outline-offset:3px}
.tour-drift.is-gone{opacity:0;transform:translateY(8px);pointer-events:none}
.tour-say{position:absolute;right:0;bottom:calc(100% + 10px);width:max-content;max-width:min(260px,calc(100vw - 32px));padding:9px 12px;border-radius:8px;background:var(--ink,#191816);color:var(--page,#f5f3ef);
  font:500 12px/1.35 var(--sans,system-ui);opacity:0;transform:translateY(6px);pointer-events:none;transition:opacity .3s,transform .4s cubic-bezier(.2,.7,.2,1)}
.tour-drift.is-saying .tour-say{opacity:1;transform:none}
.tour-drift.is-saying{box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 0 0 4px color-mix(in srgb,var(--note,#c2643f) 35%,transparent)}

/* ?record: a clean stage of the chosen ratio, centred in the browser window, for Monet Shot to record */
html.tour-record,html.tour-record body{height:100%;overflow:hidden;background:#0e0e0d}
html.tour-record body :not([data-tour-root].is-record,[data-tour-root].is-record *,:has([data-tour-root].is-record)){display:none!important}   /* everything but the film (which may sit inside another section) */
html.tour-record .sf-note,html.tour-record .sf-spec,html.tour-record [data-tour-gate],html.tour-record [data-tour-hide-on-record]{display:none!important}
html.tour-record [data-tour-root].is-record{position:fixed;left:50%;top:50%;width:var(--rw);height:var(--rh)!important;transform:translate(-50%,-50%);z-index:2147483000;cursor:none}
html.tour-record .is-record [data-tour-stage]{position:absolute;inset:0;height:auto}

@media (prefers-reduced-motion:reduce){.tour-drift,.tour-drift *,.tour-say{transition:none}}

@import url("../tour/tour.css");
/* demo/writer: a personal site for someone who writes and gives talks. A name and one line; a forty-second film of
   the site (tour.js, play driver, looping: an essay opened, a line underlined and set as a quote card, a talk played
   as slides beside its transcript, the letter signed up for); then the real thing: the newest essay's opening with
   its best line marked (select any sentence to quote it), the essay index, a compact talk player, the letter, contact.
   One colour beyond ink and paper: the highlighter, --wr-mark. ?record films the site between a title and an end card. */

.demo-writer{--wr-mark:#efdc9b;--wr-mark-2:#e4c96f;background:var(--page);color:var(--ink)}
.demo-writer ::selection{background:var(--wr-mark);color:var(--ink)}
.wr-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}

/* the highlighter, shared by the marked line, the index titles and the transcript */
.wr-hl,.wr-index b,.wr-pl-script li span{background:linear-gradient(var(--wr-mark),var(--wr-mark)) 0 58%/0% 1.02em no-repeat;-webkit-box-decoration-break:slice;box-decoration-break:slice}

/* ── top bar and masthead ── */
.wr-top{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-block:22px}
.wr-wordmark{font:400 21px/1 var(--serif);letter-spacing:-.01em;text-decoration:none;white-space:nowrap}
.wr-nav{display:flex;gap:clamp(13px,2.4vw,34px);font:500 13.5px/1 var(--sans)}
.wr-nav a{color:var(--ink-2);text-decoration:none;transition:color .25s}
.wr-nav a:hover{color:var(--ink)}
.wr-mast{padding-top:clamp(56px,10vh,124px);padding-bottom:clamp(34px,6vh,64px)}
.wr-name{margin:0;font:400 clamp(58px,10.4vw,156px)/.9 var(--serif);letter-spacing:-.038em}
.wr-line{margin:clamp(18px,2.2vw,30px) 0 0;max-width:23em;font:400 clamp(20px,2vw,28px)/1.3 var(--serif);color:var(--ink-2);text-wrap:balance}
.wr-mast .sf-note{margin-top:20px}

/* ── the film on the page: a framed window, the play button and the chapters underneath ── */
.wr-film{--tour-stage:var(--page);--tour-cap-bg:var(--ink);--tour-win-radius:0px}
.wr-film .tour-card{display:none!important}
.wr-film:not(.is-record) .wr-stage{height:auto;aspect-ratio:100/68;container-type:size;--fw:96cqw;--fx:2cqw;--fy:1.4cqw;--fh:calc(var(--fw) * .625)}
.wr-frame{position:absolute;left:var(--fx);top:var(--fy);width:var(--fw);height:var(--fh);border-radius:10px;background:var(--page);
  box-shadow:0 0 0 1px rgba(25,24,22,.11),0 34px 70px -40px rgba(25,24,22,.42),0 10px 24px -18px rgba(25,24,22,.2)}
.wr-film [data-tour-window]{box-shadow:none;background:var(--page)}
.wr-film .tour-chrome{background:var(--page-2)}
.wr-film.is-tall .tour-navs{display:none}
.wr-film:not(.is-record) .tour-ctl,.wr-film:not(.is-record).is-stack .tour-ctl{left:var(--fx);bottom:0;width:auto;height:calc(100cqh - var(--fy) - var(--fh));transform:none;padding:0;border-radius:0;background:none;box-shadow:none}
.wr-film .tour-scrub,.wr-film .tour-time{display:none}
.wr-film .tour-pp{width:30px;height:30px}
.wr-film .tour-pp svg{width:11px;height:11px}
.wr-band,.wr-end{display:none}
.wr-slug b{display:none}
.wr-film:not(.is-record) .wr-slug{position:absolute;z-index:9;left:calc(var(--fx) + 48px);right:var(--fx);top:calc(var(--fy) + var(--fh));bottom:0;display:flex;align-items:center}
.wr-steps{display:flex;gap:clamp(10px,2cqw,28px);width:100%;margin:0;padding:0;list-style:none}
.wr-steps li{flex:1;min-width:0;--p:0}
.wr-steps button{display:grid;gap:9px;width:100%;padding:8px 0;border:0;background:none;text-align:left;cursor:pointer;font:500 11.5px/1 var(--sans);letter-spacing:.12em;text-transform:uppercase;color:var(--ink-3);transition:color .3s}
.wr-steps i{display:block;height:2px;background:linear-gradient(var(--ink),var(--ink)) 0 0/calc(var(--p) * 100%) 100% no-repeat,var(--ph-line)}
.wr-steps .is-on button,.wr-steps button:hover{color:var(--ink)}
.wr-steps .is-done button{color:var(--ink-2)}
.wr-steps button:focus-visible{outline:2px solid var(--note);outline-offset:3px}
[data-tour-root]:not(.is-begun):not(.is-record):not(.is-still) .wr-steps i{background:var(--ph-line)}
@media (max-width:640px){
  .wr-film-wrap{padding-inline:8px}
  .wr-film:not(.is-record) .wr-stage{aspect-ratio:100/172;--fw:96cqw;--fx:2cqw;--fy:2cqw;--fh:calc(var(--fw) * 1.625)}
  .wr-film:not(.is-record) .wr-slug{left:calc(var(--fx) + 42px)}
  .wr-steps{gap:10px}
  .wr-steps button{font-size:10.5px;letter-spacing:.08em}
}

/* ── the site, small (1200 × 710 under the browser bar; 480 × 740 when tall) ── */
.wm{position:relative;display:flex;flex-direction:column;height:100%;overflow:hidden;background:var(--page);color:var(--ink);font:400 14px/1.4 var(--sans);text-align:left}
.wm svg{width:15px;height:15px;flex:none;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.wm-top{flex:none;display:flex;align-items:center;justify-content:space-between;height:66px;padding:0 56px;border-bottom:1px solid var(--rule)}
.wm-name{font:400 22px/1 var(--serif);letter-spacing:-.01em}
.wm-nav{display:flex;gap:30px;font:500 13.5px/1 var(--sans);color:var(--ink-2)}
.wm-nav span{position:relative;padding:7px 0}
.wm-nav .is-on,.wm-nav .is-hover{color:var(--ink)}
.wm-nav .is-on::after{content:"";position:absolute;left:0;right:0;bottom:0;height:1.5px;background:var(--ink)}
.wm-views{position:relative;flex:1;min-height:0}
.wm-view{--in:0;position:absolute;inset:0;opacity:var(--in);transform:translateY(calc((1 - var(--in)) * 12px))}
.wm-kick{margin:0;font:500 11.5px/1.3 var(--sans);letter-spacing:.12em;text-transform:uppercase;color:var(--ink-3)}
.wm-title{margin:16px 0 0;font:400 46px/1.04 var(--serif);letter-spacing:-.025em;text-wrap:balance}

/* home */
.wm-home{--in:1;display:grid;grid-template-columns:380px minmax(0,1fr);gap:76px;padding:62px 56px 0}
.wm-lede{margin:0;font:400 38px/1.12 var(--serif);letter-spacing:-.02em;text-wrap:balance}
.wm-small{margin:24px 0 0;font:500 11.5px/1.3 var(--sans);letter-spacing:.12em;text-transform:uppercase;color:var(--ink-3)}
.wm-list{margin:0;padding:0;list-style:none;border-top:1px solid var(--ink)}
.wm-row{--u:0;display:grid;grid-template-columns:64px minmax(0,1fr) 60px;align-items:baseline;gap:16px;padding:21px 0 20px;border-bottom:1px solid var(--rule)}
.wm-row time,.wm-row small{font:500 11.5px/1 var(--sans);letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3)}
.wm-row small{text-align:right}
.wm-row b{justify-self:start;max-width:100%;font:400 23px/1.25 var(--serif);letter-spacing:-.01em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
  background:linear-gradient(var(--wr-mark),var(--wr-mark)) 0 60%/calc(var(--u) * 100%) 1.02em no-repeat}
.wm-row.is-hover b{text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:5px}

/* an essay */
.wm-scroll{position:absolute;inset:0;overflow:hidden}
.wm-col{width:660px;margin:0 auto;padding:54px 0 220px}
.wm-dek{margin:16px 0 34px;font:400 18px/1.45 var(--sans);color:var(--ink-2)}
.wm-col .ph-text{font-size:20px;--lh:34px;max-width:none;margin:0 0 20px}
.wm-q{margin:0 0 20px;font:400 21px/34px var(--serif);color:var(--ink)}
.wm-hl{--sel:0;position:relative;display:inline-block;white-space:nowrap;background:linear-gradient(var(--wr-mark),var(--wr-mark)) 0 58%/calc(var(--sel) * 100%) 1.05em no-repeat}
.wm-hl-end{position:absolute;left:calc(var(--sel) * 100%);top:0;width:1px;height:100%}
.wm-tools{--in:0;position:absolute;left:50%;bottom:calc(100% + 10px);display:flex;gap:2px;padding:4px;border-radius:9px;background:var(--ink);color:var(--page);white-space:nowrap;
  font:500 13px/1 var(--sans);opacity:var(--in);transform:translate(-50%,calc((1 - var(--in)) * 6px));box-shadow:0 12px 26px -12px rgba(25,24,22,.6)}
.wm-tools::after{content:"";position:absolute;left:50%;top:100%;margin-left:-6px;border:6px solid transparent;border-top-color:var(--ink)}
.wm-tools span{display:flex;align-items:center;gap:7px;height:32px;padding:0 12px;border-radius:6px}
.wm-tools span.is-hover{background:rgba(255,255,255,.14)}
.wm-scrim{--in:0;position:absolute;inset:0;background:color-mix(in srgb,var(--page) 82%,transparent);opacity:var(--in)}
.wm-share{position:absolute;left:50%;top:47%;width:640px;transform:translate(-50%,-50%);display:grid;justify-items:center;gap:18px}
.wm-card{--in:0;width:100%;margin:0;padding:40px 52px 30px;background:var(--ph);border-radius:6px;opacity:var(--in);transform:translateY(calc((1 - var(--in)) * 30px)) scale(calc(.955 + var(--in) * .045));
  box-shadow:0 0 0 1px var(--ph-line),0 44px 80px -42px rgba(25,24,22,.5),0 12px 30px -20px rgba(25,24,22,.25)}
.wm-card-mark{display:block;height:46px;font:400 96px/.9 var(--serif);color:var(--wr-mark-2)}
.wm-card blockquote{margin:0;font:italic 400 38px/1.14 var(--serif);letter-spacing:-.015em;text-wrap:balance}
.wm-card figcaption{display:flex;justify-content:space-between;align-items:baseline;gap:16px;margin-top:30px;padding-top:16px;border-top:1px solid var(--rule);font:600 13px/1.3 var(--sans)}
.wm-card figcaption span{font-weight:400;color:var(--ink-2);text-align:right}
.wm-card code{display:block;margin-top:8px;font:500 11.5px/1 var(--mono);color:var(--ink-3)}
.wm-acts{--in:0;display:flex;gap:10px;opacity:var(--in);transform:translateY(calc((1 - var(--in)) * 8px))}
.wm-act{display:flex;align-items:center;height:38px;padding:0 18px;border-radius:99px;background:var(--ph);box-shadow:inset 0 0 0 1px var(--rule);font:500 13px/1 var(--sans);white-space:nowrap}
.wm-act.is-primary{background:var(--ink);color:var(--page);box-shadow:none}
.wm-act.is-press,.wm-sub.is-press,.wm-play.is-press,.wm-tools span.is-press,.wm-row.is-press{scale:.96}
.wm-toast{--in:0;position:absolute;left:50%;bottom:26px;display:flex;align-items:center;gap:9px;padding:11px 16px 11px 13px;border-radius:10px;background:var(--ink);color:var(--page);
  font:500 13px/1 var(--sans);white-space:nowrap;opacity:var(--in);transform:translate(-50%,calc((1 - var(--in)) * 12px));box-shadow:0 16px 34px -16px rgba(25,24,22,.6)}

/* a talk */
.wm-talk{width:996px;margin:0 auto;padding-top:34px}
.wm-talk-h .wm-title{margin-top:12px;font-size:32px}
.wm-player{display:grid;grid-template-columns:600px minmax(0,1fr);gap:36px;margin-top:24px}
.wm-screen{position:relative;aspect-ratio:16/9;overflow:hidden;border-radius:6px;background:var(--ph);box-shadow:0 0 0 1px var(--ph-line),0 26px 50px -34px rgba(25,24,22,.4)}
.wm-slide{--in:0;position:absolute;inset:0;display:grid;align-content:center;gap:14px;padding:0 54px;background:var(--ph);opacity:var(--in)}
.wm-slide[data-tour="slide-1"]{--in:1}
.wm-slide small{font:500 11px/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}
.wm-slide b{font:400 40px/1.05 var(--serif);letter-spacing:-.02em;text-wrap:balance}
.wm-slide span{font:500 13px/1 var(--sans);color:var(--ink-2)}
.wm-slide.is-big{justify-items:center;text-align:center}
.wm-slide.is-big b{font-size:46px}
.wm-slide.is-end b{font-style:italic}
.wm-slide.is-pic{padding:0}
.wm-slide.is-pic .ph{position:absolute;inset:0;border-radius:0}
.wm-play{--in:1;position:absolute;z-index:2;left:22px;bottom:20px;display:flex;align-items:center;gap:9px;height:42px;padding:0 18px 0 15px;border-radius:99px;background:var(--ink);color:var(--page);
  font:500 13.5px/1 var(--sans);opacity:var(--in);transform:translateY(calc((1 - var(--in)) * 6px));box-shadow:0 14px 30px -14px rgba(25,24,22,.6)}
.wm-play svg{width:14px;height:14px;fill:currentColor;stroke:none}
.wm-bar{display:flex;align-items:center;gap:14px;height:48px}
.wm-pp{flex:none;width:28px;height:28px;display:grid;place-items:center;border-radius:50%;box-shadow:inset 0 0 0 1px var(--rule)}
.wm-pp svg{width:11px;height:11px;fill:var(--ink);stroke:none}
.wm-pp .is-s,.wm-pp.is-playing .is-p{display:none}
.wm-pp.is-playing .is-s{display:block}
.wm-track{--p:0;position:relative;flex:1;height:2px;background:linear-gradient(var(--ink),var(--ink)) 0 0/calc(var(--p) * 100%) 100% no-repeat,var(--ph-line)}
.wm-track i{position:absolute;top:-4px;width:1px;height:10px;background:var(--ink-3)}
.wm-time{flex:none;font:500 11.5px/1 var(--mono);color:var(--ink-3)}
.wm-time b{font-weight:500;color:var(--ink)}
.wm-script{margin:0;padding:0;list-style:none;border-top:1px solid var(--ink)}
.wm-script li{display:grid;grid-template-columns:50px minmax(0,1fr);gap:10px;padding:14px 0 13px;border-bottom:1px solid var(--rule);font:400 15.5px/1.4 var(--sans);color:var(--ink-3)}
.wm-script small{font:500 11px/1.95 var(--mono)}
.wm-script span{justify-self:start}
.wm-script li.is-past{color:var(--ink-2)}
.wm-script li.is-on{color:var(--ink)}
.wm-script li.is-on span{background:linear-gradient(var(--wr-mark),var(--wr-mark)) 0 58%/100% 1.02em no-repeat}

/* the letter */
.wm-letters .wm-col{width:640px;padding-top:84px}
.wm-letters .wm-title{font-size:44px}
.wm-meta{margin:16px 0 0;font:400 15px/1.45 var(--sans);color:var(--ink-2)}
.wm-form{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;gap:16px;margin-top:36px}
.wm-field{position:relative;display:flex;align-items:center;height:50px;border-bottom:1.5px solid var(--ink);font:400 19px/1 var(--sans)}
.wm-field span:empty::before{content:"you@example.com";position:absolute;left:0;color:var(--ink-3)}
.wm-field .is-caret::after{content:"";display:inline-block;width:1.5px;height:1.1em;margin-left:1px;vertical-align:-.18em;background:var(--ink)}
.wm-sub{display:flex;align-items:center;height:50px;padding:0 24px;border-radius:2px;background:var(--ink);color:var(--page);font:500 14px/1 var(--sans);white-space:nowrap}
.wm-sub.is-done{background:var(--page-2);color:var(--ink);box-shadow:inset 0 0 0 1px var(--rule)}
.wm-done{--in:0;display:flex;align-items:center;gap:9px;margin:18px 0 0;font:400 16px/1.4 var(--sans);opacity:var(--in);transform:translateY(calc((1 - var(--in)) * 6px))}
.wm-contact{--in:0;display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin-top:58px;padding-top:20px;border-top:1px solid var(--rule);opacity:var(--in);transform:translateY(calc((1 - var(--in)) * 10px))}
.wm-contact b{font:400 28px/1 var(--serif);letter-spacing:-.01em}

/* tall: phones and 9:16 (480 × 740 under the bar) */
.wr-film.is-tall .wm-top{height:58px;padding:0 24px}
.wr-film.is-tall .wm-name{font-size:18px}
.wr-film.is-tall .wm-nav{gap:15px;font-size:12.5px}
.wr-film.is-tall .wm-title{font-size:31px}
.wr-film.is-tall .wm-home{display:block;padding:38px 26px 0}
.wr-film.is-tall .wm-lede{font-size:29px}
.wr-film.is-tall .wm-small{margin:16px 0 30px}
.wr-film.is-tall .wm-row{grid-template-columns:minmax(0,1fr) auto;gap:8px 12px;padding:17px 0 16px}
.wr-film.is-tall .wm-row b{grid-column:1/-1;grid-row:1;font-size:20px;white-space:normal}
.wr-film.is-tall .wm-row time{grid-row:2}
.wr-film.is-tall .wm-row small{grid-row:2}
.wr-film.is-tall .wm-col{width:auto;margin:0 28px;padding-top:36px}
.wr-film.is-tall .wm-dek{font-size:16px;margin-bottom:26px}
.wr-film.is-tall .wm-col .ph-text{font-size:17px;--lh:29px;margin-bottom:16px}
.wr-film.is-tall .wm-q{font-size:18px;line-height:29px;margin-bottom:16px}
.wr-film.is-tall .wm-share{width:428px;top:46%}
.wr-film.is-tall .wm-card{padding:28px 30px 22px}
.wr-film.is-tall .wm-card-mark{height:36px;font-size:76px}
.wr-film.is-tall .wm-card blockquote{font-size:29px}
.wr-film.is-tall .wm-card figcaption{flex-direction:column;gap:4px;margin-top:22px}
.wr-film.is-tall .wm-card figcaption span{text-align:left}
.wr-film.is-tall .wm-acts{gap:6px}
.wr-film.is-tall .wm-act{height:36px;padding:0 14px;font-size:12.5px}
.wr-film.is-tall .wm-talk{width:auto;margin:0;padding:30px 26px 0}
.wr-film.is-tall .wm-talk-h .wm-title{font-size:25px}
.wr-film.is-tall .wm-player{grid-template-columns:minmax(0,1fr);gap:4px;margin-top:20px}
.wr-film.is-tall .wm-slide{padding:0 30px;gap:9px}
.wr-film.is-tall .wm-slide b{font-size:25px}
.wr-film.is-tall .wm-slide.is-big b{font-size:28px}
.wr-film.is-tall .wm-play{left:16px;bottom:14px;height:36px;padding:0 14px 0 12px;font-size:12.5px}
.wr-film.is-tall .wm-time{display:none}
.wr-film.is-tall .wm-script li{padding:11px 0 10px;font-size:14px;grid-template-columns:44px minmax(0,1fr)}
.wr-film.is-tall .wm-letters .wm-col{width:auto;padding-top:46px}
.wr-film.is-tall .wm-letters .wm-title{font-size:32px}
.wr-film.is-tall .wm-form{grid-template-columns:minmax(0,1fr);gap:12px}
.wr-film.is-tall .wm-sub{justify-content:center}
.wr-film.is-tall .wm-contact{display:grid;gap:10px;margin-top:40px}
.wr-film.is-tall .wm-contact b{font-size:25px}

/* ── ?record: a title card, the site with its name and chapters above it, an end card. Stage container units. ── */
.wr-film.is-record .wr-stage{container-type:size;--fw:min(118cqh,88cqw);--fx:calc(50cqw - var(--fw) / 2);--fy:13cqh;--fh:calc(var(--fw) * .625)}
.wr-film.is-record.is-stack .wr-stage{--fw:86cqw;--fy:21cqh}
.wr-film.is-record.is-tall .wr-stage{--fw:80cqw;--fy:13cqh;--fh:calc(var(--fw) * 1.625)}
.wr-film.is-record .wr-frame{border-radius:calc(var(--fw) * .01)}
.wr-film.is-record .tour-cap{top:calc(var(--fy) + var(--fh) + 2.6cqh);bottom:auto;max-width:88cqw;padding:.62em 1.2em;border-radius:99px;font-size:min(2.6cqh,3.7cqw)}
.wr-film.is-record .wr-band{position:absolute;inset:0;z-index:10;display:grid;align-content:center;gap:2.6cqh;padding:0 10cqw;background:var(--page);opacity:clamp(0,calc(var(--tour-band,1) * 2 - 1),1)}
.wr-band p{margin:0}
.wr-band-k{font:500 max(11px,1.5cqh)/1 var(--sans);letter-spacing:.16em;text-transform:uppercase;color:var(--ink-3)}
.wr-band-h{font:400 min(17cqh,12.5cqw)/.9 var(--serif);letter-spacing:-.038em;transform:translateY(calc((1 - var(--tour-band,1)) * -2cqh))}
.wr-band-l{max-width:24em;font:400 min(3.8cqh,4.6cqw)/1.3 var(--serif);color:var(--ink-2);text-wrap:balance}
.wr-film.is-record .wr-slug{position:absolute;z-index:6;left:var(--fx);width:var(--fw);top:0;height:var(--fy);display:flex;align-items:center;justify-content:space-between;gap:4cqw;opacity:clamp(0,calc(1 - var(--tour-band,1) * 2),1)}
.wr-film.is-record .wr-slug b{display:block;flex:none;font:400 min(5cqh,4.4cqw)/1 var(--serif);letter-spacing:-.025em}
.wr-film.is-record .wr-steps{width:auto;flex:0 1 min(60cqw,72cqh);gap:2cqw}
.wr-film.is-record .wr-steps button{gap:1.1cqh;padding:0;font-size:max(10px,1.35cqh);cursor:none}
.wr-film.is-record .wr-steps i{height:max(2px,.22cqh)}
.wr-film.is-record.is-stack .wr-slug{flex-direction:column;align-items:stretch;justify-content:center;gap:2.6cqh}
.wr-film.is-record.is-stack .wr-slug b{font-size:min(7cqw,5cqh)}
.wr-film.is-record.is-stack .wr-steps{flex:none;width:100%}
.wr-film.is-record.is-stack .wr-steps button{font-size:max(10px,2.1cqw)}
.wr-film.is-record .wr-end{position:absolute;inset:0;z-index:10;display:grid;align-content:center;justify-items:center;gap:3cqh;padding:0 8cqw;text-align:center;
  background:color-mix(in srgb,var(--page) calc(min(1,var(--in,0) * 2.2) * 100%),transparent)}
.wr-end > *{opacity:clamp(0,calc(var(--in,0) * 2.2 - 1.1),1)}
.wr-end p{margin:0}
.wr-end-h{font:400 min(15cqh,12cqw)/.92 var(--serif);letter-spacing:-.038em;transform:translateY(calc((1 - var(--in,0)) * 2cqh))}
.wr-end-l{font:400 min(3.8cqh,4.8cqw)/1.3 var(--serif);color:var(--ink-2)}
.wr-end-url{margin-top:1cqh;padding:.55em 1em .6em;background:linear-gradient(var(--wr-mark),var(--wr-mark)) 0 58%/100% 1.1em no-repeat;font:500 min(2.4cqh,3.4cqw)/1 var(--mono);color:var(--ink)}

/* ── sections ── */
.wr-sec{padding-top:clamp(92px,15vh,176px)}
.wr-sec-h{display:flex;align-items:baseline;justify-content:space-between;gap:16px;padding-bottom:18px;border-bottom:1px solid var(--ink)}
.wr-h2{margin:0;font:400 clamp(32px,3.4vw,48px)/1 var(--serif);letter-spacing:-.022em}
.wr-more{font:500 13.5px/1 var(--sans);color:var(--ink-2);text-underline-offset:4px;white-space:nowrap}
.wr-more:hover{color:var(--ink)}
.wr-meta{display:flex;flex-wrap:wrap;align-items:center;margin:0;font:500 11.5px/1.6 var(--sans);letter-spacing:.12em;text-transform:uppercase;color:var(--ink-3)}
.wr-meta > * + *::before{content:"";display:inline-block;width:16px;height:1px;margin:0 10px;vertical-align:.3em;background:var(--rule)}

/* writing: the newest essay's opening, then the index */
.wr-lead{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:22px clamp(32px,6vw,104px);padding:clamp(34px,4.6vw,64px) 0 clamp(40px,5vw,72px);border-bottom:1px solid var(--rule)}
.wr-lead-t{margin:18px 0 0;font:400 clamp(34px,3.8vw,56px)/1.02 var(--serif);letter-spacing:-.026em;text-wrap:balance}
.wr-lead-t a{text-decoration:none}
.wr-lead-t a:hover{text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:.12em}
.wr-lead-body{max-width:34em}
.wr-lead-body > p{margin:0 0 1em;font:400 clamp(19px,1.5vw,21px)/1.62 var(--serif);text-wrap:pretty}
.wr-hl{color:inherit;cursor:pointer;border-radius:1px;transition:background-size 1.3s cubic-bezier(.6,.1,.25,1)}
.wr-hl.is-in,.no-js .wr-hl{background-size:100% 1.02em}
.wr-hl:hover{--wr-mark:var(--wr-mark-2)}
.wr-hl:focus-visible{outline:2px solid var(--note);outline-offset:3px}
.wr-lead-foot{display:flex;flex-wrap:wrap;align-items:baseline;gap:10px 22px;margin-top:1.6em!important;font-family:var(--sans)!important}
.wr-lead-foot .sf-btn{font-size:14px}
.wr-hint{font:400 13px/1.4 var(--sans);color:var(--ink-3)}
.wr-lead .sf-note{margin-top:14px}
.wr-index{margin:0;padding:0;list-style:none}
.wr-index a{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,8fr) minmax(0,1.2fr);align-items:baseline;gap:6px clamp(16px,2.4vw,32px);padding:24px 0 23px;border-bottom:1px solid var(--rule);text-decoration:none}
.wr-index time,.wr-len{font:500 11.5px/1.6 var(--sans);letter-spacing:.1em;text-transform:uppercase;color:var(--ink-3)}
.wr-index b{justify-self:start;font:400 clamp(22px,2vw,29px)/1.2 var(--serif);letter-spacing:-.012em;transition:background-size .7s cubic-bezier(.6,.1,.25,1)}
.wr-index a:hover b,.wr-index a:focus-visible b{background-size:100% 1.02em}
.wr-index a:focus-visible{outline:none}
.wr-dek{grid-column:2;font:400 15px/1.45 var(--sans);color:var(--ink-2)}
.wr-len{grid-row:1;grid-column:3;text-align:right}

/* talks: a compact player in the page */
.wr-player{display:grid;grid-template-columns:minmax(0,7fr) minmax(0,4fr);gap:28px clamp(28px,4.4vw,72px);padding:clamp(34px,4.6vw,60px) 0 clamp(40px,5vw,64px);border-bottom:1px solid var(--rule)}
.wr-pl-screen{position:relative;aspect-ratio:16/9;overflow:hidden;border-radius:4px;background:var(--ph);box-shadow:0 0 0 1px var(--ph-line),0 30px 64px -40px rgba(25,24,22,.42);container-type:inline-size}
.wr-pl-slide{position:absolute;inset:0;margin:0;opacity:0;transition:opacity .5s var(--ease)}
.wr-pl-slide.is-on{opacity:1}
.wr-pl-slide.ph{aspect-ratio:auto;border-radius:0;box-shadow:none}
div.wr-pl-slide{display:grid;align-content:center;gap:2.4cqw;padding:0 8cqw;background:var(--ph)}
.wr-pl-slide small{font:500 max(10px,1.6cqw)/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}
.wr-pl-slide b{font:400 6.4cqw/1.04 var(--serif);letter-spacing:-.022em;text-wrap:balance}
.wr-pl-slide span{font:500 max(11px,1.9cqw)/1 var(--sans);color:var(--ink-2)}
.wr-pl-slide.is-big{justify-items:center;text-align:center}
.wr-pl-slide.is-big b{font-size:7.2cqw}
.wr-pl-slide.is-end b{font-style:italic}
.wr-pl-pip{position:absolute;z-index:3;right:2.4cqw;bottom:2.4cqw;width:22%;aspect-ratio:4/3;padding:0;border:0;cursor:pointer;box-shadow:inset 0 0 0 1px var(--ph-line),0 10px 24px -12px rgba(25,24,22,.5);
  transition:inset .5s var(--ease),width .5s var(--ease),border-radius .5s var(--ease)}
.wr-pl-pip > span{position:absolute;left:8px;bottom:7px;font:500 10px/1 var(--sans);letter-spacing:.12em;text-transform:uppercase;color:var(--ink-3)}
.wr-pl-pip:focus-visible{outline:2px solid var(--note);outline-offset:3px}
.wr-pl-screen.is-swapped .wr-pl-pip{right:0;bottom:0;width:100%;aspect-ratio:auto;height:100%;border-radius:0;z-index:1}
.wr-pl-screen.is-swapped .wr-pl-slide{inset:auto 2.4cqw 2.4cqw auto;width:22%;height:auto;aspect-ratio:16/9;z-index:2;box-shadow:0 0 0 1px var(--ph-line),0 10px 24px -12px rgba(25,24,22,.5);pointer-events:none}
.wr-pl-screen.is-swapped div.wr-pl-slide{gap:.4cqw;padding:0 1.6cqw}
.wr-pl-screen.is-swapped .wr-pl-slide b{font-size:1.5cqw}
.wr-pl-screen.is-swapped .wr-pl-slide small,.wr-pl-screen.is-swapped .wr-pl-slide span,.wr-pl-screen.is-swapped .wr-pl-slide.ph::after{display:none}
.wr-pl-big{position:absolute;z-index:4;left:2.6cqw;bottom:2.6cqw;display:flex;align-items:center;gap:9px;height:44px;padding:0 20px 0 16px;border:0;border-radius:99px;background:var(--ink);color:var(--page);cursor:pointer;
  font:500 14px/1 var(--sans);box-shadow:0 14px 30px -14px rgba(25,24,22,.6);transition:opacity .35s ease,transform .45s var(--ease)}
.wr-pl-big svg{width:14px;height:14px;fill:currentColor}
.wr-pl-big:hover{transform:translateY(-1px)}
.wr-pl-big[hidden]{display:flex;opacity:0;transform:translateY(6px);pointer-events:none}
.wr-pl-big:focus-visible,.wr-pl-pp:focus-visible{outline:2px solid var(--note);outline-offset:3px}
.wr-pl-bar{display:flex;align-items:center;gap:14px;height:52px}
.wr-pl-pp{flex:none;width:32px;height:32px;display:grid;place-items:center;padding:0;border:0;border-radius:50%;background:none;box-shadow:inset 0 0 0 1px var(--rule);cursor:pointer}
.wr-pl-pp svg{width:12px;height:12px;fill:var(--ink)}
.wr-pl-pp .is-s,.wr-pl-pp.is-playing .is-p{display:none}
.wr-pl-pp.is-playing .is-s{display:block}
.wr-pl-track{--p:0;position:relative;flex:1;height:22px;display:flex;align-items:center}
.wr-pl-track::before{content:"";position:absolute;left:0;right:0;height:2px;background:linear-gradient(var(--ink),var(--ink)) 0 0/calc(var(--p) * 100%) 100% no-repeat,var(--ph-line)}
.wr-pl-track i{position:absolute;top:6px;width:1px;height:10px;background:var(--ink-3);pointer-events:none}
.wr-pl-track input{position:relative;z-index:1;width:100%;height:22px;margin:0;background:none;-webkit-appearance:none;appearance:none;cursor:pointer}
.wr-pl-track input::-webkit-slider-runnable-track{background:none}
.wr-pl-track input::-webkit-slider-thumb{-webkit-appearance:none;width:12px;height:12px;border-radius:50%;background:var(--ink)}
.wr-pl-track input::-moz-range-thumb{width:12px;height:12px;border:0;border-radius:50%;background:var(--ink)}
.wr-pl-track input:focus-visible{outline:2px solid var(--note);outline-offset:3px}
.wr-pl-time{flex:none;font:500 12px/1 var(--mono);color:var(--ink-3)}
.wr-pl-time b{font-weight:500;color:var(--ink)}
.wr-pl-av .sf-note{margin-top:6px}
.wr-pl-title{margin:14px 0 24px;font:400 clamp(26px,2.4vw,34px)/1.08 var(--serif);letter-spacing:-.02em;text-wrap:balance}
.wr-pl-script{margin:0;padding:0;list-style:none;border-top:1px solid var(--ink)}
.wr-pl-script li{display:grid;grid-template-columns:52px minmax(0,1fr);gap:10px;padding:14px 0 13px;border-bottom:1px solid var(--rule);font:400 16px/1.45 var(--sans);color:var(--ink-3);cursor:pointer;transition:color .3s}
.wr-pl-script li:hover{color:var(--ink-2)}
.wr-pl-script small{font:500 11px/2.1 var(--mono)}
.wr-pl-script span{justify-self:start;transition:background-size .9s cubic-bezier(.6,.1,.25,1)}
.wr-pl-script li.is-past{color:var(--ink-2)}
.wr-pl-script li.is-on{color:var(--ink)}
.wr-pl-script li.is-on span{background-size:100% 1.02em}
.wr-talks{margin:0;padding:0;list-style:none}
.wr-talks li{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,5fr) minmax(0,3fr) minmax(0,2fr);align-items:baseline;gap:6px clamp(16px,2.4vw,32px);padding:22px 0 21px;border-bottom:1px solid var(--rule)}
.wr-y,.wr-ev{font:500 11.5px/1.6 var(--sans);letter-spacing:.1em;text-transform:uppercase;color:var(--ink-3)}
.wr-talks b{font:400 clamp(20px,1.8vw,25px)/1.2 var(--serif);letter-spacing:-.01em}
.wr-ln{display:flex;justify-content:flex-end;gap:16px;font:500 13.5px/1 var(--sans)}
.wr-ln a{color:var(--ink-2);text-underline-offset:4px}
.wr-ln a:hover{color:var(--ink)}

/* the letter */
.wr-letters{margin-top:clamp(96px,15vh,176px);padding-block:clamp(72px,12vh,140px);background:var(--page-2)}
.wr-h2.is-big{max-width:15em;font-size:clamp(36px,4.6vw,68px);line-height:1.02;text-wrap:balance}
.wr-form{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;gap:18px;max-width:640px;margin-top:clamp(28px,4vw,48px)}
.wr-form .sf-field{font-size:18px;border-bottom-color:var(--ink)}
.wr-form-done{max-width:640px;margin:clamp(28px,4vw,48px) 0 0;padding:16px 0;border-bottom:1px solid var(--ink);font:400 clamp(19px,1.6vw,22px)/1.4 var(--serif)}
.wr-form-done:focus{outline:none}
.wr-small{margin:18px 0 0;font:400 14px/1.5 var(--sans);color:var(--ink-2)}
.wr-small a{color:var(--ink);text-underline-offset:3px}
.wr-letters .sf-note{margin-top:18px}

/* contact */
.wr-contact{padding-top:clamp(88px,14vh,160px);padding-bottom:clamp(64px,10vh,120px)}
.wr-contact-l{margin:0;font:400 clamp(20px,1.8vw,26px)/1.3 var(--serif);color:var(--ink-2)}
.wr-email{display:inline-block;margin-top:14px;font:400 clamp(30px,6vw,88px)/1.05 var(--serif);letter-spacing:-.03em;text-decoration:none;overflow-wrap:anywhere;
  background:linear-gradient(var(--wr-mark),var(--wr-mark)) 0 62%/0% .5em no-repeat;transition:background-size .8s cubic-bezier(.6,.1,.25,1)}
.wr-email:hover,.wr-email:focus-visible{background-size:100% .5em;outline:none}
.wr-links{display:flex;flex-wrap:wrap;gap:12px 28px;margin:clamp(28px,4vw,44px) 0 0;padding:0;list-style:none;font:500 14px/1 var(--sans)}
.wr-links a{color:var(--ink-2);text-underline-offset:4px}
.wr-links a:hover{color:var(--ink)}
.wr-contact .sf-note{margin-top:22px}
.wr-foot{display:flex;justify-content:space-between;gap:16px;padding-block:22px 34px;background:linear-gradient(var(--rule),var(--rule)) var(--gutter) 0/calc(100% - 2 * var(--gutter)) 1px no-repeat;font:400 13px/1.4 var(--sans);color:var(--ink-3)}
.wr-foot a{color:var(--ink-3);text-underline-offset:3px}

/* the quote card: on the house paper */
.wr-qpop{position:fixed;z-index:60;display:flex;align-items:center;gap:7px;height:34px;padding:0 13px;border:0;border-radius:8px;background:var(--ink);color:var(--page);font:500 13px/1 var(--sans);cursor:pointer;
  transform:translate(-50%,calc(-100% - 10px));box-shadow:0 12px 26px -12px rgba(25,24,22,.6)}
.wr-qpop[hidden]{display:none}
.wr-qpop::after{content:"";position:absolute;left:50%;top:100%;margin-left:-6px;border:6px solid transparent;border-top-color:var(--ink)}
.wr-qpop svg,.wr-qd svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.wr-qd{width:min(720px,calc(100vw - 32px));max-width:none;max-height:calc(100svh - 32px);padding:0;border:0;background:transparent;color:var(--ink);overflow:visible}
.wr-qd::backdrop{background:rgba(245,243,239,.88);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}
.wr-qd[open]{animation:wr-rise .55s cubic-bezier(.2,.7,.2,1)}
@keyframes wr-rise{from{opacity:0;transform:translateY(22px) scale(.97)}}
.wr-qc{margin:0;padding:clamp(28px,5vw,56px) clamp(24px,5.4vw,60px) clamp(22px,3.6vw,36px);background:var(--ph);border-radius:6px;
  box-shadow:0 0 0 1px var(--ph-line),0 50px 90px -50px rgba(25,24,22,.5),0 14px 34px -22px rgba(25,24,22,.25)}
.wr-qc:focus{outline:none}
.wr-qc-mark{display:block;height:clamp(36px,5vw,50px);font:400 clamp(76px,10vw,104px)/.9 var(--serif);color:var(--wr-mark-2)}
.wr-qc-q{margin:0;font:italic 400 clamp(25px,3.6vw,42px)/1.15 var(--serif);letter-spacing:-.015em;text-wrap:balance;overflow-wrap:anywhere}
.wr-qc figcaption{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:baseline;gap:4px 16px;margin-top:clamp(22px,3vw,32px);padding-top:16px;border-top:1px solid var(--rule);font:600 13.5px/1.35 var(--sans)}
.wr-qc-src{font-weight:400;color:var(--ink-2)}
.wr-qd-url{margin:14px 0 0;text-align:center;font:500 12px/1.4 var(--mono);color:var(--ink-3);overflow-wrap:anywhere}
.wr-qd-acts{display:flex;flex-wrap:wrap;justify-content:center;gap:10px;margin-top:14px}
.wr-qd-acts .sf-btn{padding:12px 18px}

@media (max-width:760px){
  .wr-lead,.wr-player{grid-template-columns:minmax(0,1fr)}
  .wr-index a{grid-template-columns:minmax(0,1fr) auto;gap:8px 16px;padding:20px 0 19px}
  .wr-index time{grid-row:1;grid-column:1}
  .wr-len{grid-row:1;grid-column:2}
  .wr-index b,.wr-dek{grid-column:1/-1}
  .wr-talks li{grid-template-columns:minmax(0,1fr) auto;gap:8px 16px}
  .wr-talks b,.wr-ev{grid-column:1/-1}
  .wr-talks .wr-y{grid-row:1}
  .wr-ln{grid-row:1;grid-column:2}
  .wr-form{grid-template-columns:minmax(0,1fr)}
  .wr-form .sf-btn{justify-content:center}
  .wr-pl-big{height:36px;padding:0 15px 0 12px;font-size:13px}
  .wr-pl-big svg{width:12px;height:12px}
  .wr-pl-pip{width:24%}
  .wr-pl-pip > span{display:none}
}
@media (max-width:420px){
  .wr-wordmark{font-size:19px}
  .wr-nav{gap:12px;font-size:13px}
}
@media (prefers-reduced-motion:reduce){
  .wr-hl,.wr-index b,.wr-pl-script span,.wr-email,.wr-pl-slide,.wr-pl-pip{transition:none}
  .wr-qd[open]{animation:none}
}
